        const FullType(BuiltList, [FullType(Tag)]),
        () => ListBuilder<Tag>(),
      )
      ..addBuilderFactory(
        const FullType(BuiltList, [FullType(Account)]),
        () => ListBuilder<Account>(),
      )
      ..addBuilderFactory(
        const FullType(BuiltList, [FullType(FeaturedTag)]),
        () => ListBuilder<FeaturedTag>(),
      )
      ..addBuilderFactory(
        const FullType(BuiltMap, [FullType(String), FullType(Marker)]),
        () => MapBuilder<String, Marker>(),
      )
      ..addBuilderFactory(
        const FullType(BuiltList, [FullType(FamiliarFollowers)]),
        () => ListBuilder<FamiliarFollowers>(),
      )
      ..addBuilderFactory(
        const FullType(BuiltList, [FullType(TrendsLink)]),
        () => ListBuilder<TrendsLink>(),
      )
      ..addBuilderFactory(
        const FullType(BuiltList, [FullType(String)]),
        () => ListBuilder<String>(),
      )
      ..addBuilderFactory(
        const FullType(BuiltList, [FullType(BuiltList)]),
        () => ListBuilder<BuiltList>(),
      )
      ..add(BaseStatus.serializer)
      ..add(const OneOfSerializer())
      ..add(const AnyOfSerializer())
      ..add(const DateSerializer())
      ..add(Iso8601DateTimeSerializer()))
    .build();

Serializers standardSerializers =
    (serializers.toBuilder()..addPlugin(StandardJsonPlugin())).build();
